  match xs {
    [] => [],
    x :: rest => if pred(x) then x :: filterInts(pred, rest) else filterInts(pred, rest)
  }

pure func foldInts(f: (int, int) -> int, acc: int, xs: [int]) -> int =
  match xs {
    [] => acc,
    x :: rest => foldInts(f, f(acc, x), rest)
  }

